/**
 * TASK: Write the checks that decide whether a RangeSpec expander is correct.
 *
 * The RangeSpec contract (think of a printer's page range):
 *   expand(spec) turns a comma-separated spec into the list of numbers it
 *   names, in the order written and WITHOUT removing duplicates.
 *   A part is either a single number ("7") or an inclusive range ("8-10").
 *   Spaces around a part or around the numbers are ignored.
 *   A range whose end is below its start contributes nothing.
 *   A null or blank spec produces an empty list.
 *   Example: expand("1-3,5, 8-10") -> [1, 2, 3, 5, 8, 9, 10]
 *            expand("5-3") -> []          expand("") -> []
 *
 * isCorrect(impl) must return true for an implementation that honours the
 * contract and false for one that does not. Some broken implementations THROW
 * instead of returning a list, so a crash counts as a failure: wrap your calls
 * in try/catch and return false if anything is thrown.
 *
 * Compare whole lists with .toString() against the text you expect, for
 * instance "[1, 2, 3]". A single well-behaved range like "1-3" is not enough --
 * three of the four bugs here survive it.
 */
interface RangeSpec {
    /* Provided -- do not edit. */
    java.util.List<Integer> expand(String spec);
}

public class RangeSpecChecker {

    public static boolean isCorrect(RangeSpec impl) {
        // TODO: call impl.expand(...) with revealing specs, compare each result's
        // toString() with the list you expect, and return false on the first
        // mismatch. A thrown exception is a failure too.
        return true;
    }
}

