import java.util.ArrayList;
import java.util.List;

public class RangeSpecCheckerTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static Object verdict(RangeSpec impl) {
        try {
            return RangeSpecChecker.isCorrect(impl);
        } catch (Throwable crash) {
            return "isCorrect threw " + crash.getClass().getSimpleName();
        }
    }

    public static void main(String[] args) {
        check("accepts the correct implementation", true, verdict(new CorrectRangeSpec()));
        check("accepts an equally correct implementation", true, verdict(new SplitOnDashRangeSpec()));
        check("rejects the exclusive-end bug", false, verdict(new ExclusiveEndRangeSpec()));
        check("rejects the ignores-single-numbers bug", false, verdict(new SkipsSingleRangeSpec()));
        check("rejects the counts-backwards-ranges bug", false, verdict(new DescendingRangeSpec()));
        check("rejects the crash-on-empty-spec bug", false, verdict(new CrashOnEmptyRangeSpec()));

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

class CorrectRangeSpec implements RangeSpec {
    public List<Integer> expand(String spec) {
        List<Integer> out = new ArrayList<>();
        if (spec == null || spec.trim().isEmpty()) {
            return out;
        }
        for (String raw : spec.split(",")) {
            String part = raw.trim();
            if (part.isEmpty()) {
                continue;
            }
            int dash = part.indexOf('-');
            if (dash < 0) {
                out.add(Integer.parseInt(part));
            } else {
                int low = Integer.parseInt(part.substring(0, dash).trim());
                int high = Integer.parseInt(part.substring(dash + 1).trim());
                for (int value = low; value <= high; value++) {
                    out.add(value);
                }
            }
        }
        return out;
    }
}

class SplitOnDashRangeSpec implements RangeSpec {
    public List<Integer> expand(String spec) {
        List<Integer> out = new ArrayList<>();
        if (spec == null) {
            return out;
        }
        for (String raw : spec.split(",")) {
            String part = raw.trim();
            if (part.isEmpty()) {
                continue;
            }
            String[] ends = part.split("-");
            if (ends.length == 1) {
                out.add(Integer.valueOf(ends[0].trim()));
            } else {
                int low = Integer.parseInt(ends[0].trim());
                int high = Integer.parseInt(ends[1].trim());
                for (int value = low; value <= high; value++) {
                    out.add(value);
                }
            }
        }
        return out;
    }
}

